// bug-01: map the household form submission to a Forgejo issue payload.
// Two required fields (activity + what-happened); the rest are optional. Field keys
// are the field LABELS (formTrigger typeVersion 2.2). Reads defensively.
const f = $input.first().json;
const get = (k) => { const v = f[k]; return (v == null ? '' : String(v)).trim(); };
const activity = get('What were you trying to do?');
const what     = get('What happened?');
const where    = get('Where were you? (which device or room)');
const when     = get('When did it happen?');
const sevRaw   = get('How much is it bothering you?');

const A = activity.toLowerCase();
let label = 'service:triage', svc = '(unknown — needs triage)', actName = 'Something else';
if (A.includes('watch'))            { label='service:plex';       svc='Plex / Jellyfin';                                   actName='Watch'; }
else if (A.includes('listen'))      { label='service:navidrome';  svc='Navidrome / Audiobookshelf';                        actName='Listen'; }
else if (A.includes('photo'))       { label='service:immich';     svc='Immich';                                            actName='Photos'; }
else if (A.includes('read'))        { label='service:komga';      svc='Audiobookshelf / Komga / Calibre-Web / Suwayomi';   actName='Read'; }
else if (A.includes('journal'))     { label='service:journaling'; svc='Memos / n8n';                                       actName='Journal'; }
else if (A.includes('dashboard') || A.includes('home page')) { label='service:homepage'; svc='Homepage'; actName='Dashboard'; }
else if (A.includes('game'))        { label='service:games';      svc='AMP / Palworld';                                    actName='Game'; }
else if (A.includes('request'))     { label='service:seerr';      svc='Seerr / Musicseerr / Shelfmark';                    actName='Request'; }

// light where-based disambiguation
let hint = '';
if (label === 'service:plex' && /tv|telly|living/i.test(where)) hint = ' (likely Plex on the TV)';

let sevLabel = 'sev:annoying', sevWord = 'Annoying (unspecified)';
if (/block/i.test(sevRaw))      { sevLabel='sev:blocking'; sevWord='Blocking'; }
else if (/annoy/i.test(sevRaw)) { sevLabel='sev:annoying'; sevWord='Annoying'; }

const labelNames = ['source:home', label, sevLabel];

const firstLine = ((what.split(/\r?\n/)[0]) || what || 'Problem reported').slice(0, 80);
const title = '[' + actName + '] ' + firstLine;

let body = '**What were you trying to do?** ' + (activity || '_(not provided)_') + '\n\n';
body += '**What happened?**\n' + (what || '_(not provided)_') + '\n\n';
body += '**Likely service(s):** ' + svc + hint + '\n';
if (where) body += '**Where / device:** ' + where + '\n';
if (when)  body += '**When:** ' + when + '\n';
body += '**Severity:** ' + sevWord + '\n';
body += '\n---\n_Filed from the household “Report a Problem” form (bug.tabaska.us). Auto-labeled; the service guess may be off — triage as needed._';

const bin = $input.first().binary || {};
const screenshotKey = Object.keys(bin)[0] || '';
const hasScreenshot = !!screenshotKey;

return [{ json: { title, body, labelNames, activity: actName, service: svc, severity: sevWord, whatShort: firstLine, hasScreenshot }, binary: $input.first().binary }];

// Resolve label NAMES -> Forgejo label IDs (Gitea 1.22 create-issue takes IDs, not
// names). Best-effort: if the labels fetch failed, post the issue with no labels.
const p = $('Build issue payload').first().json;
let labels = $input.all().map(i => i.json);
if (labels.length === 1 && Array.isArray(labels[0])) labels = labels[0];
labels = labels.filter(x => x && x.name != null && x.id != null);
const byName = {};
for (const l of labels) byName[l.name] = l.id;
const ids = (p.labelNames || []).map(n => byName[n]).filter(x => x != null);
return [{ json: { title: p.title, body: p.body, labelIds: ids, hasScreenshot: p.hasScreenshot },
          binary: $('Build issue payload').first().binary }];

// Screenshot side-branch: needs the new issue number (from Create) AND the uploaded
// binary (from the form trigger). Rename the first binary to a fixed key 'screenshot'
// so the upload node has a static field name. No screenshot -> return [] (branch ends).
const issue = $input.first().json;
const num = issue && issue.number;
const src = $('Report a Problem').first();
const bin = (src && src.binary) ? src.binary : {};
const key = Object.keys(bin)[0] || '';
if (!num || !key) return [];
const meta = bin[key] || {};
const filename = meta.fileName || ('screenshot' + (meta.fileExtension ? '.' + meta.fileExtension : '.png'));
return [{ json: { issueNumber: num, filename }, binary: { screenshot: bin[key] } }];

// Build the ntfy + Discord notification payloads from the created issue.
const issue = $('Create Forgejo issue').first().json;
const p = $('Build issue payload').first().json;
const num = issue && issue.number ? issue.number : '?';
const link = 'https://git.tabaska.us/home/household-bugs/issues/' + num;
// ntfy Title header must be ASCII-safe (no emoji in headers) -> emoji only in body.
const title = 'New bug report: ' + p.activity;
const msg = '\u{1F41E} ' + p.whatShort + '\n\nService: ' + p.service + '\nSeverity: ' + p.severity + '\n' + link;
const priority = /block/i.test(p.severity) ? '4' : '3';
const dw = ($env.DISCORD_BUGS_WEBHOOK || '').trim();
const discordSet = dw.length > 0;
const discordBody = { content: '\u{1F41E} **New household bug report** — ' + p.activity + ' (' + p.severity + ')\n' + p.whatShort + '\n' + link };
// The verification synthetic-submit probe files a report carrying this sentinel; the
// issue is still created (so the create path is exercised end-to-end) but we SKIP the
// ntfy/Discord ping so a monitoring run never buzzes the operator's phone. The probe
// deletes the issue afterward, leaving zero residue.
const notify = !/n8n-bugreport-probe/i.test(p.whatShort || '');
return [{ json: { title, msg, priority, link, discordSet, discordBody, notify } }];
